using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Xml;
using System.Xml.Linq;
using Npgsql;
using NpgsqlTypes;
using AvenChart.Api.Models;
namespace AvenChart.Api.Data;

public sealed class PatientXmlExchangeRepository(NpgsqlDataSource source)
{
    public async Task<string?> ExportAsync(string patientId, CancellationToken ct) { await using var c = await source.OpenConnectionAsync(ct); var p = await ReadAsync(c, patientId, ct); if (p is null) return null; var x = new XElement("avenchart-patient", new XAttribute("version", "1"), new XElement("patient", new XElement("patient-id", p.Id), new XElement("first-name", p.First), new XElement("last-name", p.Last), new XElement("date-of-birth", p.Dob), E("sex", p.Sex), E("street", p.Street), E("city", p.City), E("state", p.State), E("postal-code", p.Zip), E("phone-home", p.Home), E("phone-cell", p.Cell), E("email", p.Email))); return new XDocument(new XDeclaration("1.0", "utf-8", null), x).ToString(); }
    public async Task<PatientXmlPreview?> PreviewAsync(PatientXmlImportRequest r, CancellationToken ct) { var p = Parse(r.PatientId, r.Xml); await using var c = await source.OpenConnectionAsync(ct); var current = await ReadAsync(c, r.PatientId, ct); if (current is null) return null; return new(current.Id, p.FirstName, p.LastName, p.DateOfBirth, p.Sex, p.Street, p.City, p.State, p.PostalCode, p.PhoneHome, p.PhoneCell, p.Email, Changed(current, p)); }
    public async Task<PatientXmlImportResult?> ImportAsync(PatientXmlImportRequest r, string user, CancellationToken ct) { var p = Parse(r.PatientId, r.Xml); await using var c = await source.OpenConnectionAsync(ct); await using var tx = await c.BeginTransactionAsync(ct); var old = await ReadAsync(c, r.PatientId, ct); if (old is null) return null; var audit = Guid.NewGuid(); await using (var q = c.CreateCommand()) { q.Transaction = tx; q.CommandText = "update patients set first_name=@first,last_name=@last,date_of_birth=@dob,sex=@sex,street=@street,city=@city,state=@state,postal_code=@zip,phone_home=@home,phone_cell=@cell,email=@email where canonical_id=@id; insert into patient_xml_exchange_audits(id,patient_id,imported_by,prior_values,payload_sha256) values(@audit,@id,@user,@prior,@sha);"; Add(q, "first", p.FirstName); Add(q, "last", p.LastName); q.Parameters.AddWithValue("dob", DateOnly.Parse(p.DateOfBirth)); Add(q, "sex", p.Sex); Add(q, "street", p.Street); Add(q, "city", p.City); Add(q, "state", p.State); Add(q, "zip", p.PostalCode); Add(q, "home", p.PhoneHome); Add(q, "cell", p.PhoneCell); Add(q, "email", p.Email); q.Parameters.AddWithValue("id", old.Id); q.Parameters.AddWithValue("audit", audit); q.Parameters.AddWithValue("user", user); q.Parameters.Add("prior", NpgsqlDbType.Jsonb).Value = JsonSerializer.Serialize(old); q.Parameters.AddWithValue("sha", Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(r.Xml))).ToLowerInvariant()); await q.ExecuteNonQueryAsync(ct); } await tx.CommitAsync(ct); return new(audit, old.Id, DateTimeOffset.UtcNow.ToString("O"), Changed(old, p)); }
    public async Task<bool> RollbackAsync(Guid audit, string user, CancellationToken ct) { await using var c = await source.OpenConnectionAsync(ct); await using var tx = await c.BeginTransactionAsync(ct); await using var q = c.CreateCommand(); q.Transaction = tx; q.CommandText = "select patient_id,prior_values from patient_xml_exchange_audits where id=@id and rolled_back_at is null for update;"; q.Parameters.AddWithValue("id", audit); await using var r = await q.ExecuteReaderAsync(ct); if (!await r.ReadAsync(ct)) return false; var id = r.GetString(0); var p = JsonSerializer.Deserialize<Row>(r.GetString(1)); await r.DisposeAsync(); if (p is null) return false; await using var u = c.CreateCommand(); u.Transaction = tx; u.CommandText = "update patients set first_name=@first,last_name=@last,date_of_birth=@dob,sex=@sex,street=@street,city=@city,state=@state,postal_code=@zip,phone_home=@home,phone_cell=@cell,email=@email where canonical_id=@id;update patient_xml_exchange_audits set rolled_back_at=now(),rolled_back_by=@user where id=@audit;"; Add(u, "first", p.First); Add(u, "last", p.Last); u.Parameters.AddWithValue("dob", DateOnly.Parse(p.Dob)); Add(u, "sex", p.Sex); Add(u, "street", p.Street); Add(u, "city", p.City); Add(u, "state", p.State); Add(u, "zip", p.Zip); Add(u, "home", p.Home); Add(u, "cell", p.Cell); Add(u, "email", p.Email); u.Parameters.AddWithValue("id", id); u.Parameters.AddWithValue("audit", audit); u.Parameters.AddWithValue("user", user); await u.ExecuteNonQueryAsync(ct); await tx.CommitAsync(ct); return true; }
    static XElement E(string n, string? v) => new(n, v ?? ""); static void Add(NpgsqlCommand q, string n, string? v) => q.Parameters.AddWithValue(n, (object?)v ?? DBNull.Value);
    static PatientXmlPreview Parse(string id, string xml) { if (string.IsNullOrWhiteSpace(xml) || xml.Length > 1_000_000) throw new ArgumentException("XML payload is required and must not exceed 1 MB."); using var sr = new StringReader(xml); using var xr = XmlReader.Create(sr, new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit, XmlResolver = null, MaxCharactersInDocument = 1_000_000 }); var doc = XDocument.Load(xr); var p = doc.Root?.Element("patient") ?? throw new ArgumentException("Expected avenchart-patient/patient XML."); string V(string n) => p.Element(n)?.Value.Trim() ?? ""; var first = V("first-name"); var last = V("last-name"); var dob = V("date-of-birth"); if (first.Length == 0 || last.Length == 0 || !DateOnly.TryParse(dob, out _)) throw new ArgumentException("First name, last name, and ISO date of birth are required."); return new(id, first, last, dob, N("sex"), N("street"), N("city"), N("state"), N("postal-code"), N("phone-home"), N("phone-cell"), N("email"), []); string? N(string n) => string.IsNullOrWhiteSpace(V(n)) ? null : V(n); }
    static async Task<Row?> ReadAsync(NpgsqlConnection c, string id, CancellationToken ct) { await using var q = c.CreateCommand(); q.CommandText = "select canonical_id,first_name,last_name,date_of_birth::text,sex,street,city,state,postal_code,phone_home,phone_cell,email from patients where canonical_id=@id or pubpid=@id limit 1;"; q.Parameters.AddWithValue("id", id); await using var r = await q.ExecuteReaderAsync(ct); return await r.ReadAsync(ct) ? new(r.GetString(0), r.GetString(1), r.GetString(2), r.GetString(3), S(r, 4), S(r, 5), S(r, 6), S(r, 7), S(r, 8), S(r, 9), S(r, 10), S(r, 11)) : null; }
    static string? S(NpgsqlDataReader r, int i) => r.IsDBNull(i) ? null : r.GetString(i); static IReadOnlyList<string> Changed(Row a, PatientXmlPreview b) { var z = new List<string>(); if (a.First != b.FirstName) z.Add("firstName"); if (a.Last != b.LastName) z.Add("lastName"); if (a.Dob != b.DateOfBirth) z.Add("dateOfBirth"); if (a.Email != b.Email) z.Add("email"); if (a.Cell != b.PhoneCell) z.Add("phoneCell"); return z; }
    sealed record Row(string Id, string First, string Last, string Dob, string? Sex, string? Street, string? City, string? State, string? Zip, string? Home, string? Cell, string? Email);
}
